add_filter( 'wp_nav_menu_objects', 'perfectpixel_account_menu_label_logged_out' );

function perfectpixel_account_menu_label_logged_out( $items ) {
	if ( is_user_logged_in() || ! function_exists( 'wc_get_page_id' ) ) {
		return $items;
	}
	$account_id = (int) wc_get_page_id( 'myaccount' );
	foreach ( $items as $item ) {
		if ( 'page' === $item->object && (int) $item->object_id === $account_id ) {
			$item->title = '{{account_menu_logged_out_label}}';
		}
	}
	return $items;
}
